class Solution {
  public long minCost(int[] arr, int[] brr, long k) {
    int n = arr.length;
    long direct = 0;
    for (int i = 0; i < n; i++) direct += Math.abs(arr[i] - brr[i]);
    int[] a = arr.clone(), b = brr.clone();
    java.util.Arrays.sort(a);
    java.util.Arrays.sort(b);
    long sorted = k;
    for (int i = 0; i < n; i++) sorted += Math.abs(a[i] - b[i]);
    return Math.min(direct, sorted);
  }
}
